/**
 * Unit tests for SlackWebApiClient and loadWorkspaceNotificationConfig.
 *
 * Test matrix:
 *
 * SlackWebApiClient.postMessage:
 *   1. Success — returns { ts, channel }
 *   2. HTTP failure — throws with status code
 *   3. ok: false — throws with Slack error
 *   4. Missing ts field — throws
 *
 * createSlackWebApiClient:
 *   5. Disabled (no botToken) — returns null
 *   6. Disabled (no channelId) — returns null
 *   7. Enabled — returns client instance
 *
 * SlackWebApiClient.updateMessage:
 *   8. Success — resolves without throwing
 *   9. HTTP failure — throws with status code
 *  10. ok: false — throws with Slack error
 *
 * loadWorkspaceNotificationConfig:
 *  11. Field present — returns config with channelId
 *  12. Field absent (no notifications key) — returns null
 *  13. Malformed yaml (unreadable file) — returns null
 *  14. notifications present but slack absent — returns null
 *  15. channel_id present but empty string — returns null
 */

import { describe, it, expect, vi, afterEach } from "vitest";
import { mkdtempSync, writeFileSync, mkdirSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import {
  SlackWebApiClient,
  createSlackWebApiClient,
} from "../src/slack/slack-web-api-client.js";
import { loadWorkspaceNotificationConfig } from "../src/config/workspace-config.js";

const BOT_TOKEN = "xoxb-test-token";
const CHANNEL_ID = "C0123456789";

afterEach(() => {
  vi.unstubAllGlobals();
});

function makeClient(): SlackWebApiClient {
  return new SlackWebApiClient({ botToken: BOT_TOKEN, channelId: CHANNEL_ID });
}

function mockFetchJson(body: unknown, ok = true, status = 200): ReturnType<typeof vi.fn> {
  const fn = vi.fn().mockResolvedValue({
    ok,
    status,
    text: async () => JSON.stringify(body),
    json: async () => body,
  });
  vi.stubGlobal("fetch", fn);
  return fn;
}

function mockFetchHttpError(status = 500): ReturnType<typeof vi.fn> {
  const fn = vi.fn().mockResolvedValue({
    ok: false,
    status,
    text: async () => "Internal Server Error",
    json: async () => { throw new Error("not JSON"); },
  });
  vi.stubGlobal("fetch", fn);
  return fn;
}

// ── postMessage ───────────────────────────────────────────────────────────────

describe("SlackWebApiClient.postMessage", () => {
  it("1. returns ts and channel on success", async () => {
    mockFetchJson({ ok: true, ts: "1234567890.123456", channel: CHANNEL_ID });
    const client = makeClient();
    const result = await client.postMessage("Hello");
    expect(result.ts).toBe("1234567890.123456");
    expect(result.channel).toBe(CHANNEL_ID);
  });

  it("sends bearer auth header and correct channel", async () => {
    const fn = mockFetchJson({ ok: true, ts: "9999.0001", channel: CHANNEL_ID });
    const client = makeClient();
    await client.postMessage("Hello");
    const [url, init] = fn.mock.calls[0] as [string, RequestInit];
    expect(url).toContain("chat.postMessage");
    const headers = init.headers as Record<string, string>;
    expect(headers["Authorization"]).toBe(`Bearer ${BOT_TOKEN}`);
    const body = JSON.parse(init.body as string) as Record<string, unknown>;
    expect(body["channel"]).toBe(CHANNEL_ID);
    expect(body["text"]).toBe("Hello");
