import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { InMemoryThreadStore } from "../src/adapters/in-memory-thread-store.js";
import { RedisThreadStore, parseRedisUrl, buildRedisThreadStore } from "../src/adapters/redis-thread-store.js";
import type { NotificationThreadStorePort } from "../src/ports/notification-thread-store.port.js";

// ---------- InMemoryThreadStore tests ----------

describe("InMemoryThreadStore", () => {
  let store: InMemoryThreadStore;

  beforeEach(() => {
    store = new InMemoryThreadStore();
  });

  it("getFeatureThread returns null for missing key", async () => {
    const result = await store.getFeatureThread("ws1", "feat1");
    expect(result).toBeNull();
  });

  it("setFeatureThread and getFeatureThread round-trip", async () => {
    await store.setFeatureThread("ws1", "feat1", "1234567890.123456");
    const result = await store.getFeatureThread("ws1", "feat1");
    expect(result).toBe("1234567890.123456");
  });

  it("deleteFeatureThread removes the key", async () => {
    await store.setFeatureThread("ws1", "feat1", "1234567890.123456");
    await store.deleteFeatureThread("ws1", "feat1");
    expect(await store.getFeatureThread("ws1", "feat1")).toBeNull();
  });

  it("getTaskThread returns null for missing key", async () => {
    const result = await store.getTaskThread("ws1", "feat1", "T1");
    expect(result).toBeNull();
  });

  it("setTaskThread and getTaskThread round-trip", async () => {
    await store.setTaskThread("ws1", "feat1", "T1", "9999999999.000001");
    const result = await store.getTaskThread("ws1", "feat1", "T1");
    expect(result).toBe("9999999999.000001");
  });

  it("deleteTaskThread removes the key", async () => {
    await store.setTaskThread("ws1", "feat1", "T1", "9999999999.000001");
    await store.deleteTaskThread("ws1", "feat1", "T1");
    expect(await store.getTaskThread("ws1", "feat1", "T1")).toBeNull();
  });

  it("deleteAllTaskThreads removes all task keys for the feature", async () => {
    await store.setTaskThread("ws1", "feat1", "T1", "ts1");
    await store.setTaskThread("ws1", "feat1", "T2", "ts2");
    await store.setTaskThread("ws1", "feat1", "T3", "ts3");
    await store.setTaskThread("ws1", "feat2", "T1", "ts_other_feature");
    await store.setFeatureThread("ws1", "feat1", "feature_ts");

    await store.deleteAllTaskThreads("ws1", "feat1");

    expect(await store.getTaskThread("ws1", "feat1", "T1")).toBeNull();
    expect(await store.getTaskThread("ws1", "feat1", "T2")).toBeNull();
    expect(await store.getTaskThread("ws1", "feat1", "T3")).toBeNull();
    // Other-feature task key must NOT be deleted
    expect(await store.getTaskThread("ws1", "feat2", "T1")).toBe("ts_other_feature");
    // Feature thread key must NOT be deleted
    expect(await store.getFeatureThread("ws1", "feat1")).toBe("feature_ts");
  });

  it("keys are workspace-scoped — same feature in different workspaces are independent", async () => {
    await store.setFeatureThread("ws1", "feat1", "ts_ws1");
    await store.setFeatureThread("ws2", "feat1", "ts_ws2");
    expect(await store.getFeatureThread("ws1", "feat1")).toBe("ts_ws1");
    expect(await store.getFeatureThread("ws2", "feat1")).toBe("ts_ws2");
  });

  it("snapshot returns all stored entries", async () => {
    await store.setFeatureThread("ws1", "feat1", "fts");
    await store.setTaskThread("ws1", "feat1", "T1", "tts");
    const snap = store.snapshot();
    expect(snap["slack:feature_thread:ws1:feat1"]).toBe("fts");
    expect(snap["slack:task_thread:ws1:feat1:T1"]).toBe("tts");
  });

  it("clear removes all entries", async () => {
    await store.setFeatureThread("ws1", "feat1", "ts1");
    store.clear();
    expect(await store.getFeatureThread("ws1", "feat1")).toBeNull();
  });
});

// ---------- RedisThreadStore tests (mocked) ----------

describe("RedisThreadStore", () => {
  const mockGet = vi.fn();
  const mockSet = vi.fn();
  const mockDel = vi.fn();
  const mockConnect = vi.fn();
  const mockDisconnect = vi.fn();
  let mockScanKeys: string[] = [];

  function makeStore(): RedisThreadStore {
    const store = new RedisThreadStore("redis://localhost:6379");
    // Inject fake client by casting
    const fake = {
      connect: mockConnect.mockResolvedValue(undefined),
      disconnect: mockDisconnect.mockResolvedValue(undefined),
      get: mockGet,
      set: mockSet,
      del: mockDel,
      scanIterator: async function* (_opts?: unknown) {
        for (const key of mockScanKeys) {
          yield key;
        }
      },
    };
    (store as unknown as { client: unknown; connected: boolean }).client = fake;
    (store as unknown as { connected: boolean }).connected = true; // skip auto-connect
    return store;
  }

  beforeEach(() => {
    vi.resetAllMocks();
    mockScanKeys = [];
  });

  it("getFeatureThread returns value from Redis", async () => {
    mockGet.mockResolvedValue("1234567890.000000");
    const store = makeStore();
    const result = await store.getFeatureThread("ws1", "feat1");
    expect(result).toBe("1234567890.000000");
    expect(mockGet).toHaveBeenCalledWith("slack:feature_thread:ws1:feat1");
  });

  it("getFeatureThread returns null for missing key", async () => {
    mockGet.mockResolvedValue(null);
    const store = makeStore();
    const result = await store.getFeatureThread("ws1", "feat1");
    expect(result).toBeNull();
  });

  it("setFeatureThread calls Redis SET with correct key", async () => {
    mockSet.mockResolvedValue("OK");
    const store = makeStore();
    await store.setFeatureThread("ws1", "feat1", "ts_val");
    expect(mockSet).toHaveBeenCalledWith("slack:feature_thread:ws1:feat1", "ts_val");
  });

  it("deleteFeatureThread calls Redis DEL with correct key", async () => {
    mockDel.mockResolvedValue(1);
    const store = makeStore();
    await store.deleteFeatureThread("ws1", "feat1");
    expect(mockDel).toHaveBeenCalledWith("slack:feature_thread:ws1:feat1");
  });

  it("getTaskThread returns value from Redis", async () => {
    mockGet.mockResolvedValue("9999999999.000001");
    const store = makeStore();
    const result = await store.getTaskThread("ws1", "feat1", "T2");
    expect(result).toBe("9999999999.000001");
    expect(mockGet).toHaveBeenCalledWith("slack:task_thread:ws1:feat1:T2");
  });

  it("getTaskThread returns null for missing key", async () => {
    mockGet.mockResolvedValue(null);
    const store = makeStore();
    const result = await store.getTaskThread("ws1", "feat1", "T2");
    expect(result).toBeNull();
  });

  it("setTaskThread calls Redis SET with correct key", async () => {
    mockSet.mockResolvedValue("OK");
    const store = makeStore();
    await store.setTaskThread("ws1", "feat1", "T2", "ts_val");
    expect(mockSet).toHaveBeenCalledWith("slack:task_thread:ws1:feat1:T2", "ts_val");
  });

  it("deleteTaskThread calls Redis DEL with correct key", async () => {
    mockDel.mockResolvedValue(1);
    const store = makeStore();
    await store.deleteTaskThread("ws1", "feat1", "T2");
    expect(mockDel).toHaveBeenCalledWith("slack:task_thread:ws1:feat1:T2");
  });

  it("deleteAllTaskThreads scans and deletes matching keys", async () => {
    mockScanKeys = ["slack:task_thread:ws1:feat1:T1", "slack:task_thread:ws1:feat1:T2"];
    mockDel.mockResolvedValue(1);
    const store = makeStore();
    await store.deleteAllTaskThreads("ws1", "feat1");
    expect(mockDel).toHaveBeenCalledWith("slack:task_thread:ws1:feat1:T1");
    expect(mockDel).toHaveBeenCalledWith("slack:task_thread:ws1:feat1:T2");
  });

  it("deleteAllTaskThreads handles empty scan result gracefully", async () => {
    mockScanKeys = [];
    const store = makeStore();
    await store.deleteAllTaskThreads("ws1", "feat1");
    expect(mockDel).not.toHaveBeenCalled();
  });

  it("deleteAllTaskThreads deletes each scanned key individually", async () => {
    mockScanKeys = ["slack:task_thread:ws1:feat1:T1", "slack:task_thread:ws1:feat1:T2", "slack:task_thread:ws1:feat1:T3"];
    mockDel.mockResolvedValue(1);
    const store = makeStore();
    await store.deleteAllTaskThreads("ws1", "feat1");
    expect(mockDel).toHaveBeenCalledTimes(3);
  });

  it("connection failure propagates from get", async () => {
    const store = new RedisThreadStore("redis://localhost:6379");
    const fakeClient = {
      connect: vi.fn().mockRejectedValue(new Error("ECONNREFUSED")),
      get: vi.fn(),
      set: vi.fn(),
      del: vi.fn(),
      scan: vi.fn(),
    };
    (store as unknown as { client: unknown }).client = fakeClient;
    await expect(store.getFeatureThread("ws1", "feat1")).rejects.toThrow("ECONNREFUSED");
  });

  it("write failure propagates from set", async () => {
    mockSet.mockRejectedValue(new Error("READONLY You can't write against a read only replica"));
    const store = makeStore();
    await expect(store.setFeatureThread("ws1", "feat1", "ts")).rejects.toThrow("READONLY");
  });

  it("delete failure propagates from del", async () => {
    mockDel.mockRejectedValue(new Error("ERR unknown command"));
    const store = makeStore();
    await expect(store.deleteFeatureThread("ws1", "feat1")).rejects.toThrow("ERR unknown command");
  });
});

// ---------- Config helpers ----------

describe("parseRedisUrl", () => {
  afterEach(() => {
    delete process.env["REDIS_URL"];
  });

  it("returns the REDIS_URL env value when set", () => {
    process.env["REDIS_URL"] = "redis://localhost:6380";
    expect(parseRedisUrl()).toBe("redis://localhost:6380");
  });

  it("returns null when REDIS_URL is not set", () => {
    delete process.env["REDIS_URL"];
    expect(parseRedisUrl()).toBeNull();
  });
});

describe("buildRedisThreadStore", () => {
  afterEach(() => {
    delete process.env["REDIS_URL"];
  });

  it("returns null when REDIS_URL is absent", () => {
    delete process.env["REDIS_URL"];
    expect(buildRedisThreadStore()).toBeNull();
  });

  it("returns a RedisThreadStore instance when REDIS_URL is set", () => {
    process.env["REDIS_URL"] = "redis://localhost:6379";
    const store = buildRedisThreadStore();
    expect(store).toBeInstanceOf(RedisThreadStore);
  });
});

